session_start();

if (!isset($_SESSION['farmer'])) {
    header('Location: index.php');
    exit;
}
if (!isset($_SESSION['diagnosis'])) {
    header('Location: diagnose.php');
    exit;
}

$d = $_SESSION['diagnosis'];
$modelVersion = $d['model_version'] ?? 'yolo-agri-v1';
$detectionCount = isset($d['detections']) ? count($d['detections']) : 0;
$affectedArea = isset($d['affected_area_percentage']) ? (float)$d['affected_area_percentage'] : null;
?>
