    <div class="meta-row"><span class="k">Confidence Level: </span><span class="v"><?php echo htmlspecialchars($d['confidence']); ?>% Accuracy</span></div>
    <?php if ($affectedArea !== null && $affectedArea > 0): ?>
      <div class="meta-row"><span class="k">Affected Canopy Area: </span><span class="v"><?php echo htmlspecialchars($affectedArea); ?>%</span></div>
    <?php endif; ?>
    <?php if ($detectionCount > 0): ?>
      <div class="meta-row"><span class="k">Localized Lesions: </span><span class="v"><?php echo htmlspecialchars($detectionCount); ?> box(es) detected</span></div>
    <?php endif; ?>

    <hr class="divider">

    <div class="section-title">🛡️ Recommended Precautions & Advisory</div>

    <p class="description-text"><?php echo htmlspecialchars($d['description']); ?></p>

