      <?php foreach ($d['precautions'] as $p): ?>
        <div class="precaution-card">
          <div class="precaution-icon"><?php echo htmlspecialchars($p['icon'] ?? '🌱'); ?></div>
          <div>
            <h4><?php echo htmlspecialchars($p['title']); ?></h4>
            <p><?php echo htmlspecialchars($p['text']); ?></p>
          </div>
        </div>
      <?php endforeach; ?>
    <?php endif; ?>

